// See zonos3-generation.h.
#include "zonos3-generation.h"

#include "json.hpp"
#include "zonos3-generation-json.h"   // generated by CMake: zonos3_generation_json[], zonos3_generation_json_len

#include <cmath>

const zonos3_generation_registry & zonos3_generation() {
    static const zonos3_generation_registry r = [] {
        const auto doc = nlohmann::json::parse(
            std::string((const char *) zonos3_generation_json, zonos3_generation_json_len));
        const auto & sampling = doc.at("sampling");
        const auto & seconds = doc.at("audio_max_seconds");
        zonos3_generation_registry out;
        out.sample_rate = doc.at("sample_rate").get<int>();
        out.sampling.temperature = sampling.at("temperature").get<float>();
        out.sampling.top_p = sampling.at("top_p").get<float>();
        out.sampling.min_p = sampling.at("min_p").get<float>();
        out.sampling.repetition_penalty = sampling.at("repetition_penalty").get<float>();
        out.sampling.topk = sampling.at("topk").get<int>();
        out.sampling.repetition_window = sampling.at("repetition_window").get<int>();
        out.sampling.repetition_codebooks = sampling.at("repetition_codebooks").get<int>();
        out.silence_prefill_default_frames = doc.at("silence_prefill_frames").at("default").get<int>();
        out.silence_prefill_max_frames = doc.at("silence_prefill_frames").at("max").get<int>();
        out.decode_context_frames = doc.at("decode_context_frames").get<int>();
        out.reference_max_frames = doc.at("reference_max_frames").get<int>();
        out.max_frames = doc.at("max_frames").get<int>();
        out.stream_codebooks_default = doc.at("stream_codebooks").at("default").get<int>();
        out.stream_codebooks_first_only = doc.at("stream_codebooks").at("scope").get<std::string>() == "first";
        out.reference_audio_max_seconds = seconds.at("reference").get<double>();
        out.upload_max_seconds = seconds.at("upload").get<double>();
        out.edit_max_seconds = seconds.at("edit").get<double>();
        out.output_limit_dbfs = doc.at("output_limit_dbfs").get<double>();
        return out;
    }();
    return r;
}

void zonos3_soft_limit(float * pcm, size_t n) {
    static const float knee = (float) std::pow(10.0, zonos3_generation().output_limit_dbfs / 20.0);
    static const float width = 1.0f - knee;
    for (size_t i = 0; i < n; ++i) {
        const float a = std::fabs(pcm[i]);
        if (a > knee) pcm[i] = std::copysign(knee + width * std::tanh((a - knee) / width), pcm[i]);
    }
}
